import java.util.ArrayList;
import java.util.List;

public class NumberFilter {
    public static List<Integer> evens(List<Integer> nums) {
        List<Integer> out = new ArrayList<>();
        for (int n : nums) {
            if (n % 2 == 0) {
                out.add(n);
            }
        }
        return out;
    }
}

