import java.util.List;
import java.util.stream.Collectors;

public class NumberFilter {
    public static List<Integer> evens(List<Integer> nums) {
        return nums.stream()
                .filter(n -> n % 2 == 0)
                .collect(Collectors.toList());
    }
}

